window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-756011baa5649cc6"]={"versions": [{"id": "FIG-756011baa5649cc6", "releases": ["R2.1.20"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (<code>sd Icu_DeInit</code>) zur De-Initialisierungssequenz des Input Capture Unit (ICU) Treibers innerhalb der AUTOSAR-Basissoftware (Microcontroller Abstraction Layer, MCAL). Es modelliert die synchrone Interaktion zwischen dem Treiber-Nutzer und dem ICU-Treiber.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>ICU User</strong>: Aufrufende Entität (z. B. ein BSW-Modul höherer Schichten oder die ECU-Zustandsverwaltung).\n</li><li><strong>ICU Driver</strong>: Ausführendes MCAL-Treibermodul für ICU-Kanäle.\n</li><li><strong>Schnittstelle / API</strong>: Synchoner Funktionsaufruf <code>Icu_DeInit(void)</code> mit Rückgabepfeil <code>return</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der <code>ICU User</code> setzt den synchronen Aufruf <code>Icu_DeInit(void)</code> an den <code>ICU Driver</code> ab.\n</li><li>Der <code>ICU Driver</code> führt die De-Initialisierung durch, deaktiviert die zugehörigen Benachrichtigungen sowie Interrupts und bringt die Hardware in den durch die Konfigurationsstruktur vorgegebenen Ruhezustand.\n</li><li>Der Aufruf kehrt synchron via <code>return</code> zum <code>ICU User</code> zurück.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Vorbedingung</strong>: Die genutzte Hardware ist entsprechend der referenzierten Konfigurationsstruktur konfiguriert.\n</li><li><strong>Nachbedingungen</strong>:\n a) Sämtliche Notifications sind deaktiviert.\n b) Alle verwendeten Interrupts sind deaktiviert.\n</li><li>Verbindlicher synchroner Ablauf für das Herunterfahren des Treibers im Rahmen des BSW-Zustandsmanagements.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-a252e83c2eeb0ca5", "releases": ["R3.0.7"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (<code>sd Icu_DeInit</code>) zur De-Initialisierungssequenz des Input Capture Unit (ICU) Treibers innerhalb der AUTOSAR-Basissoftware (Microcontroller Abstraction Layer, MCAL). Es modelliert die synchrone Interaktion zwischen dem Treiber-Nutzer und dem ICU-Treiber.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Generic Elements::Icu User</strong>: Aufrufende Entität aus dem Namensraum der generischen ICU-Elemente.\n</li><li><strong>«module» Icu::Icu</strong>: Zielmodul des Aufrufs mit Modulstereotyp und Dekompositionssymbol.\n</li><li><strong>Schnittstelle / API</strong>: Synchone Operation <code>Icu_DeInit()</code> mit Rückkehrnachricht <code>Icu_DeInit</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der <code>Generic Elements::Icu User</code> sendet den synchronen Aufruf <code>Icu_DeInit()</code> an das Modul <code>Icu::Icu</code>.\n</li><li>Während der Aktivierungsphase führt <code>Icu::Icu</code> die De-Initialisierungsroutinen aus.\n</li><li>Der synchrone Kontrollfluss kehrt mit der Rückkehrnachricht <code>Icu_DeInit</code> zum Aufrufer zurück.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Spezifikationsmetadaten: Notizfeld mit <code>Status: Proposed by TO as per SWS ICU 2.0.0</code> sowie Platzhaltern für <code>Description:</code> und <code>Comments:</code>.\n</li><li>Explizite funktionale Vor- und Nachbedingungen sind nicht im Diagramm annotiert.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-f551292ae8eeed7f", "releases": ["R3.1.5"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (<code>sd Icu_DeInit</code>) zur De-Initialisierungssequenz des Input Capture Unit (ICU) Treibers innerhalb der AUTOSAR-Basissoftware (Microcontroller Abstraction Layer, MCAL). Es modelliert die synchrone Interaktion zwischen dem Treiber-Nutzer und dem ICU-Treiber.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Generic Elements::Icu User</strong>: Aufrufende Entität aus dem Namensraum der generischen ICU-Elemente.\n</li><li><strong>«module» Icu::Icu</strong>: Zielmodul des Aufrufs mit Modulstereotyp und Dekompositionssymbol.\n</li><li><strong>Schnittstelle / API</strong>: Synchone Operation <code>Icu_DeInit()</code> mit Rückkehrnachricht <code>Icu_DeInit</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der <code>Generic Elements::Icu User</code> sendet den synchronen Aufruf <code>Icu_DeInit()</code> an das Modul <code>Icu::Icu</code>.\n</li><li>Während der Aktivierungsphase führt <code>Icu::Icu</code> die De-Initialisierungsroutinen aus.\n</li><li>Der synchrone Kontrollfluss kehrt mit der Rückkehrnachricht <code>Icu_DeInit</code> zum Aufrufer zurück.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li>Spezifikationsmetadaten: Notizfeld mit <code>Status: Proposed by TO as per SWS ICU 2.0.0</code> sowie Platzhaltern für <code>Description:</code> und <code>Comments:</code>.\n</li><li>Explizite funktionale Vor- und Nachbedingungen sind nicht im Diagramm annotiert.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-01f690a915678109", "releases": ["R3.2.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Sequenzdiagramm (<code>sd Icu_DeInit</code>) zur De-Initialisierungssequenz des Input Capture Unit (ICU) Treibers innerhalb der AUTOSAR-Basissoftware (Microcontroller Abstraction Layer, MCAL). Es modelliert die synchrone Interaktion zwischen dem Treiber-Nutzer und dem ICU-Treiber.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<ul class=\"fig-list\"><li><strong>Icu User</strong>: Aufrufende Entität/Nutzerkomponente des Treibers.\n</li><li><strong>«module» Icu</strong>: Zielmodul mit Stereotyp <code>«module»</code> und Dekompositionssymbol.\n</li><li><strong>Schnittstelle / API</strong>: Synchrone Operation <code>Icu_DeInit()</code> mit Rückkehrnachricht <code>Icu_DeInit()</code>.\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<ol class=\"fig-list\"><li>Der <code>Icu User</code> ruft synchron die Funktion <code>Icu_DeInit()</code> am Modul <code>Icu</code> auf.\n</li><li>Das Modul <code>Icu</code> deaktiviert im Zuge der De-Initialisierung alle Benachrichtigungen und Interrupts und belässt die Hardware im referenzierten Konfigurationszustand.\n</li><li>Die Ausführung kehrt über die Rückkehrantwort <code>Icu_DeInit()</code> zum <code>Icu User</code> zurück.\n</li></ol>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<ul class=\"fig-list\"><li><strong>Vorbedingung</strong>: Die verwendete Hardware ist gemäß der referenzierten Konfigurationsstruktur konfiguriert (<code>Used HW is configured according to referenced configuration structure</code>).\n</li><li><strong>Nachbedingungen</strong>:\n a) Sämtliche Notifications sind deaktiviert (<code>all notifications are disabled</code>).\n b) Alle verwendeten Interrupts sind deaktiviert (<code>all used interrupts are disabled</code>).\n</li><li>Spezifikationsmetadaten: Zusätzliches Notizfeld mit <code>Status: Proposed by TO as per SWS ICU 2.0.0</code>, <code>Description:</code> und <code>Comments:</code>.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-756011baa5649cc6", "to": "FIG-a252e83c2eeb0ca5", "fr": "R2.1.20", "tr": "R3.0.7", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Lebenslinie links von <code>ICU User</code> in <code>Generic Elements::Icu User</code> umbenannt.\n</li><li>Lebenslinie rechts von <code>ICU Driver</code> in <code>«module» Icu::Icu</code> mit Subsystem-/Dekompositionssymbol geändert.\n</li><li>Aufruf-Signatur von <code>Icu_DeInit(void)</code> in <code>Icu_DeInit()</code> geändert.\n</li><li>Rückkehr-Nachricht von <code>return</code> in <code>Icu_DeInit</code> umbenannt.\n</li><li>Vor- und Nachbedingungs-Notiz links oben entfernt.\n</li><li>Metadaten-Notiz unten ergänzt (<code>Status: Proposed by TO as per SWS ICU 2.0.0</code>, <code>Description:</code>, <code>Comments:</code>).\n</li></ul>"}, {"from": "FIG-a252e83c2eeb0ca5", "to": "FIG-f551292ae8eeed7f", "fr": "R3.0.7", "tr": "R3.1.5", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-f551292ae8eeed7f", "to": "FIG-01f690a915678109", "fr": "R3.1.5", "tr": "R3.2.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Lebenslinie links von <code>Generic Elements::Icu User</code> in <code>Icu User</code> umbenannt.\n</li><li>Lebenslinie rechts von <code>«module» Icu::Icu</code> in <code>«module» Icu</code> umbenannt.\n</li><li>Rückkehr-Nachricht von <code>Icu_DeInit</code> in <code>Icu_DeInit()</code> geändert.\n</li><li>Notiz mit Vor- und Nachbedingungen links wieder eingefügt (<code>Used HW is configured according to referenced configuration structure</code>, <code>a) all notifications are disabled</code>, <code>b) all used interrupts are disabled</code>).\n</li></ul>"}]};
